return ['domain'=>'wp-seo-multilingual','plural-forms'=>'nplurals=1; plural=0;','language'=>'th','project-id-version'=>'WPML SEO 5.2.0','pot-creation-date'=>'2026-10-20 07:35+0000','po-revision-date'=>'2026-10-20 07:35+0000','x-generator'=>'PTC (Private Translation Cloud)','messages'=>['WPML SEO'=>'WPML SEO','https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-seo/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-seo/','Multilingual support for popular SEO plugins'=>'การรองรับหลายภาษาสำหรับปลั๊กอิน SEO ยอดนิยม','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com/'=>'http://www.onthegosystems.com/','Hreflang tags moved to your sitemap'=>'แท็ก hreflang ถูกย้ายไปยังแผนผังเว็บไซต์ของคุณแล้ว','To improve SEO and avoid duplicate hreflang data, WPML now adds hreflang tags only to your sitemap. We have disabled the hreflang tags in your page\'s <head> section.'=>'เพื่อปรับปรุง SEO และหลีกเลี่ยงข้อมูล hreflang ที่ซ้ำซ้อน ขณะนี้ WPML จะเพิ่มแท็ก hreflang ลงในแผนผังเว็บไซต์ของคุณเท่านั้น เราได้ปิดการใช้งานแท็ก hreflang ในส่วน <head> ของหน้าเว็บของคุณแล้ว','If you prefer to keep them in the <head>, you can re-enable this option in %1$sWPML → Settings → URLs and SEO%2$s.'=>'หากคุณต้องการเก็บไว้ในส่วน <head> คุณสามารถเปิดใช้งานตัวเลือกนี้อีกครั้งได้ใน %1$sWPML → การตั้งค่า → URL และ SEO%2$s','Sitemaps for each language'=>'แผนผังเว็บไซต์สำหรับแต่ละภาษา','Each language runs on its own domain, so each one has its own sitemap. Submit all of them to Google Search Console.'=>'แต่ละภาษาทำงานบนโดเมนของตัวเอง ดังนั้นแต่ละภาษาจึงมีแผนผังเว็บไซต์ของตัวเอง โปรดส่งแผนผังเว็บไซต์ทั้งหมดไปยัง Google Search Console','Translated by WPML'=>'แปลโดย WPML','This field shows the translation that WPML String Translation serves. Click "Edit anyway" to override it.'=>'ช่องนี้แสดงคำแปลที่ WPML String Translation ให้บริการ คลิก “แก้ไขต่อไป” เพื่อแทนที่','Edit anyway'=>'แก้ไขต่อไป','Your text overrides the WPML translation. Leave the field empty to let WPML translate it.'=>'ข้อความของคุณจะแทนที่การแปลของ WPML เว้นช่องนี้ให้ว่างไว้เพื่อให้ WPML แปลให้','This section has the Yoast SEO texts of your categories, tags and other taxonomy terms.'=>'ส่วนนี้ประกอบด้วยข้อความ Yoast SEO ของหมวดหมู่ แท็ก และคำศัพท์ในอนุกรมวิธานอื่น ๆ ของคุณ']];